CREATE EXTENSION IF NOT EXISTS citext;
-- BoozeHub PostgreSQL schema. Monetary fields use South African cents.
CREATE TYPE user_role AS ENUM ('CUSTOMER','STORE_OWNER','STORE_MANAGER','STORE_STAFF','DRIVER','SUPPORT_AGENT','ADMIN','SUPER_ADMIN');
CREATE TYPE store_status AS ENUM ('PENDING','UNDER_REVIEW','APPROVED','SUSPENDED','REJECTED','EXPIRED');
CREATE TYPE verification_status AS ENUM ('PENDING','VERIFIED','FAILED','REVIEW_REQUIRED');
CREATE TYPE inventory_status AS ENUM ('IN_STOCK','LOW_STOCK','OUT_OF_STOCK','HIDDEN');
CREATE TYPE order_status AS ENUM ('PENDING_PAYMENT','PAID','SENT_TO_STORE','STORE_ACCEPTED','PREPARING','READY_FOR_COLLECTION','DRIVER_ASSIGNED','DRIVER_ARRIVED_AT_STORE','PICKED_UP','EN_ROUTE','ARRIVED','AGE_VERIFICATION','DELIVERED','FAILED_DELIVERY','CANCELLED','REFUNDED');
CREATE TYPE compliance_status AS ENUM ('PENDING','CLEARED','FAILED','REVIEW_REQUIRED');

CREATE TABLE users (id uuid PRIMARY KEY, email citext UNIQUE NOT NULL, password_hash text NOT NULL, role user_role NOT NULL, email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (user_id uuid PRIMARY KEY REFERENCES users(id), date_of_birth date NOT NULL, age_verified boolean NOT NULL DEFAULT false, verification_method text, verification_status verification_status NOT NULL DEFAULT 'PENDING', verification_date timestamptz, verification_provider text, verification_reference text);
CREATE TABLE addresses (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), line1 text NOT NULL, suburb text NOT NULL, city text NOT NULL, province text NOT NULL, postal_code text, latitude numeric(9,6), longitude numeric(9,6), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stores (id uuid PRIMARY KEY, business_name text NOT NULL, trading_name text NOT NULL, owner_name text NOT NULL, contact_email citext NOT NULL, phone text NOT NULL, address_id uuid REFERENCES addresses(id), province text NOT NULL, municipality text, status store_status NOT NULL DEFAULT 'PENDING', delivery_radius_km numeric(6,2) NOT NULL, default_commission_bps integer, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE store_licences (id uuid PRIMARY KEY, store_id uuid NOT NULL REFERENCES stores(id), licence_number text NOT NULL UNIQUE, licence_type text NOT NULL, issuing_authority text NOT NULL, issue_date date, expiry_date date NOT NULL, verification_status verification_status NOT NULL DEFAULT 'PENDING', verification_date timestamptz, verified_by uuid REFERENCES users(id));
CREATE TABLE store_staff (store_id uuid REFERENCES stores(id), user_id uuid REFERENCES users(id), role user_role NOT NULL CHECK (role IN ('STORE_OWNER','STORE_MANAGER','STORE_STAFF')), PRIMARY KEY(store_id,user_id));
CREATE TABLE product_categories (id uuid PRIMARY KEY, name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE products (id uuid PRIMARY KEY, store_id uuid NOT NULL REFERENCES stores(id), category_id uuid REFERENCES product_categories(id), name text NOT NULL, brand text, description text, volume_ml integer, abv numeric(5,2), sku text, barcode text, price_cents integer NOT NULL CHECK(price_cents >= 0), cost_price_cents integer, sale_price_cents integer CHECK(sale_price_cents >= 0), active boolean NOT NULL DEFAULT true, featured boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(store_id, sku));
CREATE TABLE inventory (product_id uuid PRIMARY KEY REFERENCES products(id), quantity integer NOT NULL CHECK(quantity >= 0), low_stock_threshold integer NOT NULL DEFAULT 0, status inventory_status NOT NULL DEFAULT 'IN_STOCK');
CREATE TABLE carts (id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(user_id), store_id uuid NOT NULL REFERENCES stores(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_cart_per_customer ON carts(customer_id);
CREATE TABLE cart_items (id uuid PRIMARY KEY, cart_id uuid NOT NULL REFERENCES carts(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK(quantity > 0), UNIQUE(cart_id,product_id));
CREATE TABLE order_groups (id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(user_id), total_cents integer NOT NULL DEFAULT 0); -- V2 multi-store boundary
CREATE TABLE orders (id uuid PRIMARY KEY, order_group_id uuid REFERENCES order_groups(id), customer_id uuid NOT NULL REFERENCES customers(user_id), store_id uuid NOT NULL REFERENCES stores(id), delivery_address_id uuid NOT NULL REFERENCES addresses(id), status order_status NOT NULL DEFAULT 'PENDING_PAYMENT', subtotal_cents integer NOT NULL, discount_cents integer NOT NULL DEFAULT 0, delivery_fee_cents integer NOT NULL DEFAULT 0, platform_fee_cents integer NOT NULL DEFAULT 0, payment_fee_cents integer NOT NULL DEFAULT 0, store_commission_cents integer NOT NULL DEFAULT 0, driver_payout_cents integer NOT NULL DEFAULT 0, total_cents integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE order_items (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), product_id uuid NOT NULL REFERENCES products(id), product_name text NOT NULL, unit_price_cents integer NOT NULL, quantity integer NOT NULL CHECK(quantity > 0));
CREATE TABLE order_compliance (order_id uuid PRIMARY KEY REFERENCES orders(id), customer_age_verified boolean NOT NULL, store_licence_verified boolean NOT NULL, delivery_age_check_required boolean NOT NULL DEFAULT true, delivery_age_check_completed boolean NOT NULL DEFAULT false, delivery_age_check_result verification_status, delivery_refusal_reason text, compliance_status compliance_status NOT NULL DEFAULT 'PENDING');
CREATE TABLE order_status_history (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), status order_status NOT NULL, actor_id uuid REFERENCES users(id), reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id), provider text NOT NULL, provider_reference text, status text NOT NULL, amount_cents integer NOT NULL, UNIQUE(provider,provider_reference));
CREATE TABLE drivers (user_id uuid PRIMARY KEY REFERENCES users(id), status text NOT NULL, verification_status verification_status NOT NULL DEFAULT 'PENDING');
CREATE TABLE deliveries (id uuid PRIMARY KEY, order_id uuid NOT NULL UNIQUE REFERENCES orders(id), driver_id uuid REFERENCES drivers(user_id), status text NOT NULL, age_verified_at timestamptz, age_verification_result verification_status);
CREATE TABLE province_compliance_rules (id uuid PRIMARY KEY, province text NOT NULL UNIQUE, rules jsonb NOT NULL, active boolean NOT NULL DEFAULT true, updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY, actor_id uuid REFERENCES users(id), actor_role user_role, action text NOT NULL, entity_type text NOT NULL, entity_id uuid, previous_value jsonb, new_value jsonb, ip_address inet, created_at timestamptz NOT NULL DEFAULT now());
